import { splitProps, type JSX } from 'solid-js';
import { skeletonStyleKeys } from '../lib/core';
import styles from './skeleton.module.scss';
export interface SkeletonProps extends JSX.HTMLAttributes<HTMLDivElement> {}
export function Skeleton(props: SkeletonProps) {
	const [local, rest] = splitProps(props, ['class']);
	return <div {...rest} aria-hidden={rest['aria-hidden'] ?? 'true'} class={`${styles[skeletonStyleKeys.base]} ${local.class ?? ''}`} />;
}
export default Skeleton;

@use '../../../styles/variables/colors' as *;

@keyframes tile-skeleton-pulse {
	50% {
		opacity: 0.5;
	}
}

.skeleton {
	animation: tile-skeleton-pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
	border-radius: var(--tile-skeleton-radius, $radius);
	background-color: var(--tile-skeleton-background, $accent);
}
